import{_ as t,c as r,o as a,ag as i}from"./chunks/framework.C86mscM5.js";const _=JSON.parse('{"title":"Secret 管理","description":"","frontmatter":{},"headers":[],"relativePath":"devops/security-reliability/secrets.md","filePath":"devops/security-reliability/secrets.md","lastUpdated":1788092044000}'),l={name:"devops/security-reliability/secrets.md"};function o(s,e,c,n,d,h){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="secret-管理" tabindex="-1">Secret 管理 <a class="header-anchor" href="#secret-管理" aria-label="Permalink to &quot;Secret 管理&quot;">​</a></h1><p>Secret 包括密码、Token、私钥、证书和数据库连接凭据。目标不仅是“不提交到 Git”，还包括限制读取、缩短有效期、避免泄漏并能够轮换。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><ol><li>由受控系统生成或导入，记录用途和所有者。</li><li>按环境和工作负载隔离，只授权需要的主体读取。</li><li>在运行时通过文件、Secret Provider 或受控环境变量注入。</li><li>定期轮换，并支持应用在不中断服务的情况下更新。</li><li>过期、离职或泄漏时立即吊销，保留审计记录。</li></ol><h2 id="各阶段做法" tabindex="-1">各阶段做法 <a class="header-anchor" href="#各阶段做法" aria-label="Permalink to &quot;各阶段做法&quot;">​</a></h2><ul><li><strong>本地开发</strong>：提交 <code>.env.example</code>，真实值放在被忽略文件或本地 Secret 工具中。</li><li><strong>CI/CD</strong>：使用环境级受保护变量，禁止向 Fork PR 暴露生产 Secret；优先用 OIDC 换取短期凭据。</li><li><strong>镜像构建</strong>：使用 BuildKit secret mount 等临时注入方式，不能写入 <code>ARG</code>、<code>ENV</code> 或镜像层。</li><li><strong>Kubernetes</strong>：Secret 的 Base64 不是加密；启用静态加密、最小 RBAC，并评估 Vault、云 Secret Manager 或 External Secrets。</li><li><strong>前端</strong>：发送给浏览器的任何值都不再是 Secret。公开 API Key 必须通过来源限制、配额和后端授权降低风险。</li></ul><h2 id="泄漏响应" tabindex="-1">泄漏响应 <a class="header-anchor" href="#泄漏响应" aria-label="Permalink to &quot;泄漏响应&quot;">​</a></h2><p>立即吊销或轮换凭据，再检查使用日志、影响范围和持久化位置。仅从 Git 历史删除字符串不能让已经暴露的凭据重新安全。</p><h2 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h2><ul><li>是否有明确所有者、用途、环境和过期时间？</li><li>日志、错误、构建产物和遥测是否完成脱敏？</li><li>应用能否同时接受新旧凭据以完成无中断轮换？</li><li>是否监控异常读取、认证失败和即将到期的证书？</li></ul>',10)]))}const p=t(l,[["render",o]]);export{_ as __pageData,p as default};
